    /**
     * Method to retrieve the KYCDocument via KYCDocumentFetchOneSummary
     * @param 	summary KYCDocumentFetchOneSummary 
     * @return 	KYCDocumentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public KYCDocument getKYCDocument( KYCDocumentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "KYCDocumentFetchOneSummary arg cannot be null" );
    	
    	KYCDocument entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a KYCDocument
        	// --------------------------------------
        	CompletableFuture<KYCDocument> futureEntity = queryGateway.query(new FindKYCDocumentQuery( new LoadKYCDocumentFilter( summary.getKYCDocumentId() ) ), ResponseTypes.instanceOf(KYCDocument.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate KYCDocument with id " + summary.getKYCDocumentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


